<?php require __DIR__.'/inc/page_helpers.php'; $types=['all','hat','shirt','pants','tshirt','face','head'];$type=(string)($_GET['type']??'all');if(!in_array($type,$types,true))$type='all';$q=$type==='all'?$db->query('SELECT * FROM catalog_items ORDER BY id DESC'):$db->prepare('SELECT * FROM catalog_items WHERE type=? ORDER BY id DESC');if($type!=='all')$q->execute([$type]);$items=$q->fetchAll();page_start('Catalog');?><section class="Panel"><h1>Catalog</h1><div class="tabs"><?php foreach($types as $t):?><a href="/Catalog.php?type=<?=e($t)?>"><?=e(ucfirst($t))?></a><?php endforeach;?></div><div class="tile-grid"><?php foreach($items as $i):?><article class="tile"><a href="/Item.php?id=<?=(int)$i['id']?>"><?=e($i['name'])?></a><p><?=e($i['description'])?></p><small><?=e($i['type'])?> · <?=(int)$i['price']?> tickets</small></article><?php endforeach;?><?php if(!$items):?><p>Catalog is empty.</p><?php endif;?></div></section><?php page_end();